package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class HelpFormatter_renderWrappedText_TriageGen1Test {

    private HelpFormatter helpFormatter;
    private Method renderWrappedTextMethod;

    @Before
    public void setUp() throws Exception {
        helpFormatter = new HelpFormatter();
        // Accessing protected method via reflection
        renderWrappedTextMethod = HelpFormatter.class.getDeclaredMethod(
                "renderWrappedText", 
                StringBuffer.class, 
                int.class, 
                int.class, 
                String.class
        );
        renderWrappedTextMethod.setAccessible(true);
    }

    private StringBuffer invokeRenderWrappedText(StringBuffer sb, int width, int nextLineTabStop, String text) throws Exception {
        return (StringBuffer) renderWrappedTextMethod.invoke(helpFormatter, sb, width, nextLineTabStop, text);
    }

    @Test
    public void testRenderWrappedText_NoWrapNeeded() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "Short text";
        int width = 20;
        int nextLineTabStop = 2;

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // When pos == -1, it appends rtrim(text)
        assertEquals("Short text", result.toString());
    }

    @Test
    public void testRenderWrappedText_SingleWrap() throws Exception {
        StringBuffer sb = new StringBuffer();
        // "Hello World" is 11 chars. width 5 will force a wrap.
        String text = "Hello World";
        int width = 5;
        int nextLineTabStop = 2;
        helpFormatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // Line 1: findWrapPos finds pos at 5 ("Hello")
        // sb appends "Hello" + \n
        // Loop: text becomes "  World" (2 spaces + trim "World")
        // findWrapPos("  World", 5, 2) -> "  Wor" (pos 5)
        // ... this continues until pos is -1
        // Since the logic is complex, we check if it contains the expected newline and content
        String output = result.toString();
        assertEquals(true, output.contains("\n"));
        assertEquals(true, output.contains("World"));
    }

    @Test
    public void testRenderWrappedText_ImmediateWrapAtStart() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "LongTextThatWraps";
        int width = 4;
        int nextLineTabStop = 2;
        helpFormatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // Should wrap multiple times
        String output = result.toString();
        assertEquals(true, output.contains("\n"));
    }

    @Test
    public void testRenderWrappedText_TextWithTrailingSpaces() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "TrimMe    ";
        int width = 20;
        int nextLineTabStop = 2;

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // pos will be -1 because "TrimMe    " fits in 20
        // rtrim should remove spaces
        assertEquals("TrimMe", result.toString());
    }

    @Test
    public void testRenderWrappedText_ComplexMultiLine() throws Exception {
        StringBuffer sb = new StringBuffer();
        // Create a string that will definitely trigger the while(true) loop multiple times
        String text = "This is a very long sentence that must be wrapped multiple times.";
        int width = 10;
        int nextLineTabStop = 4;
        helpFormatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        String output = result.toString();

        // Verify padding is applied (the loop adds padding + text.substring(pos).trim())
        // After first wrap, subsequent lines should have 4 spaces
        String[] lines = output.split("\n");
        if (lines.length > 1) {
            // Check if second line starts with 4 spaces (or more if padding + text)
            // Note: the code does: text = padding + text.substring(pos).trim();
            // then sb.append(rtrim(text.substring(0, pos)))
            // So the padding is part of the string being rtrimmed and appended.
            assertEquals(true, lines[1].startsWith("    "));
        }
    }

    @Test
    public void testRenderWrappedText_WidthSmallerThanPadding() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "Testing width constraints";
        int width = 2; 
        int nextLineTabStop = 5;
        helpFormatter.setNewLine("\n");

        // This tests the edge case where width is so small that the padding itself 
        // might influence the wrap position calculation.
        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        assertEquals(true, result.length() > 0);
    }
}
